import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BqDA2HS7.js";const k=JSON.parse('{"title":"Codex CLI 接入","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/codex.md","filePath":"integrations/codex.md"}'),o={name:"integrations/codex.md"};function r(n,e,d,c,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="codex-cli-接入" tabindex="-1">Codex CLI 接入 <a class="header-anchor" href="#codex-cli-接入" aria-label="Permalink to &quot;Codex CLI 接入&quot;">​</a></h1><p>Codex CLI 可通过独立标准模型网关使用规划策略。Router 不替 Codex 执行工具、组织技能、 压缩上下文或安排任务，也不向标准模型请求注入 DAG。</p><h2 id="启动独立模型服务" tabindex="-1">启动独立模型服务 <a class="header-anchor" href="#启动独立模型服务" aria-label="Permalink to &quot;启动独立模型服务&quot;">​</a></h2><p>准备网关的版本化 JSON 配置，引用自己的 provider、模型、价格、策略及凭证环境变量。 配置示意与完整边界见<a href="https://github.com/AEALab/RefractRouter/blob/main/docs/independent-model-router.md" target="_blank" rel="noreferrer">仓库中的独立模型接口说明</a>。 空 <code>planningRouting</code> 不是可运行配置，DSH 设置不能直接当作独立网关凭证。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refractrouter-gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /绝对路径/gateway.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runs-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /绝对路径/router-evidence</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --preflight</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refractrouter-gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /绝对路径/gateway.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runs-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /绝对路径/router-evidence</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8088</span></span></code></pre></div><p>预检不调用模型。服务认证由配置中的 <code>authTokenEnv</code> 指定；这个 Router token 与上游模型 key 分开。 非回环部署另需要 TLS、访问控制和运维措施，本版不把本机验收称为完整团队部署。</p><h2 id="模型与协议" tabindex="-1">模型与协议 <a class="header-anchor" href="#模型与协议" aria-label="Permalink to &quot;模型与协议&quot;">​</a></h2><p>Base URL：<code>http://127.0.0.1:8088/v1</code>。</p><p>虚拟模型：<code>refract/static</code>、<code>refract/stage</code>、<code>refract/task</code>、<code>refract/composite</code>、 <code>refract/advisor</code>、<code>refract/escalation</code>。<code>/v1/models</code> 只列出配置预检可用的策略。 Chat Completions 与 Responses 提供已接通的文本/function 子集。</p><p>Codex 自定义 provider 使用 <code>wire_api=&quot;responses&quot;</code>，设置 <code>request_max_retries=0</code>、 <code>stream_max_retries=0</code>，保留原有模型目录和提示。根据网关能力配置执行推理断言； 混合或未配置推理档位时不要强行传一个不匹配值。</p><p>项目提供 <code>validation/codex/model_catalog.py</code> 为本机目录追加路由项。它保留宿主指令， 不把目录中的提示上传给 Router。使用方法和 CLI 参数以安装的 Codex 版本与仓库指南为准。</p><h2 id="哪些能力不能假设已接通" tabindex="-1">哪些能力不能假设已接通 <a class="header-anchor" href="#哪些能力不能假设已接通" aria-label="Permalink to &quot;哪些能力不能假设已接通&quot;">​</a></h2><p>当前网关不能悄悄忽略媒体、托管 web search、custom tool、加密推理历史或 <code>previous_response_id</code> 增量存储。请求须符合完整文本/function 历史与 <code>store=false</code> 的范围。 本机 CLI 验收不代表 Codex App、远程代理或所有品牌客户端完整兼容。</p><h2 id="stage-composite-的工具证据" tabindex="-1">Stage / Composite 的工具证据 <a class="header-anchor" href="#stage-composite-的工具证据" aria-label="Permalink to &quot;Stage / Composite 的工具证据&quot;">​</a></h2><p>纯 Base URL 工具结果通常没有可信退出状态。基本工具往返可工作，结果仍可能标为无法分类， 不能证明自然重复失败接管。</p><p>可选客户端证据适配利用 Codex 原生事件与 PostToolUse hook 进行唯一配对，再提交工具事实。 接线、hook 信任及限制详见<a href="https://github.com/AEALab/RefractRouter/blob/main/docs/client-tool-evidence.md" target="_blank" rel="noreferrer">客户端工具证据说明</a>。 不要为了接入绕过日常 hook 信任或覆盖已有 hooks。无法唯一匹配的并行结果保持未知。</p><h2 id="验证范围" tabindex="-1">验证范围 <a class="header-anchor" href="#验证范围" aria-label="Permalink to &quot;验证范围&quot;">​</a></h2><p>DSH 与 Codex CLI 是当前维护的接入范围。Static 工具往返、协议转换和部分策略接线已有证据； 每策略、每 Judge 的真实质量与客户端矩阵分别核对。历史 Hermes 实验保留，不作为本次新增支持承诺。</p>`,18)])])}const C=a(o,[["render",r]]);export{k as __pageData,C as default};
